def max_damage(n, a, b):
    # Initialize variables to store counts of fire and frost skills
    cnt = [0, 0]

    # Count occurrences of each skill type (fire=0, frost=1)
    for i in range(n):
        if a[i] == 'fire':
            cnt[0] += 1
        else:
            cnt[1] += 1

    # Initialize variables to store total damages and skills lists
    zzz = 0
    skill = [[], []]

    # Store damage values for each skill type in separate lists
    for i in range(n):
        if a[i] == 'fire':
            skill[0].append(b[i])
        else:
            skill[1].append(b[i])

    # Sort skills lists in descending order to maximize damage
    skill[0].sort(reverse=True)
    skill[1].sort(reverse=True)

    # Calculate total damages based on counts and doubling rules
    if abs(cnt[1]-cnt[0]) <= 1:
        zzz = sum(skill[cnt.index(max(cnt))])*2
    else:
        # Handle corner cases where one type of skill is present
        if cnt.index(min(cnt)) == 0:
            for i in range(len(skill[1])):
                zzz += (skill[1][i]*2)
            remaining_damage = sum(skill[0])
            zzz += remaining_damage
        else:
            for i in range(len(skill[0])):
                zzz += (skill[0][i]*2)
            remaining_damage = sum(skill[1])
            zzz += remaining_damage

    # Return maximum possible damage value
    return max(zzz, sum(b))

